const base = env.get("HA_URL");
const token = env.get("HA_TOKEN");
const options = msg.questionOptions || (msg.payload && typeof msg.payload === "object" ? msg.payload : {});
const transport = options.transport || env.get("ALEXA_TRANSPORT") || "alexa_media";
const entity = options.alexa_device || env.get("ALEXA_ENTITY");
const device = options.device_id || env.get("ALEXA_DEVICE_ID");
const grouped = Array.isArray(options.targets) && options.targets.length > 0;
if (!base || !token || (!grouped && (transport === "alexa_media" ? !entity : !device)) || !["alexa_media", "alexa_devices"].includes(transport)) {
    node.error("Set HA_URL, HA_TOKEN and a target for the selected launch method.");
    return null;
}
if (msg.sensorRead) {
    if (msg.statusCode !== 200 || !msg.payload || typeof msg.payload.state !== 'string' || ["unknown", "unavailable"].includes(msg.payload.state)) {
        node.error("Sensor read failed; question was not sent."); return null;
    }
    options.text = "The sensor reads " + msg.payload.state + " " + (msg.payload.attributes?.unit_of_measurement || "") + ". Would you like me to act?";
}
const managed = options.managed === true || grouped;
msg.method = "POST";
msg.url = base.replace(/\/+$/, "") + "/api/services/script/activate_alexa_actionable_notification" + (managed ? "_managed" : "");
msg.headers = {"Authorization": "Bearer " + token, "Content-Type": "application/json"};
msg.payload = {text: options.text || "Did the Node-RED question work?", event_id: options.event_id || "node_red_test", suppress_confirmation: options.suppress_confirmation ?? false};
if (grouped) msg.payload.targets = options.targets;
else if (transport === "alexa_media") msg.payload.alexa_device = entity;
else Object.assign(msg.payload, {transport, device_id: device, invocation_name: options.invocation_name || env.get("ALEXA_INVOCATION") || "actionable notifications"});
for (const key of ["confirmation_yes", "confirmation_no"]) if (typeof options[key] === "string") msg.payload[key] = options[key];
if (managed) Object.assign(msg.payload, {timeout_seconds: options.timeout_seconds ?? 60, audio_only: options.audio_only ?? false});
return msg;

const sensor = env.get("HA_SENSOR");
if (!sensor) return [null, msg];
const base = env.get("HA_URL"), token = env.get("HA_TOKEN");
if (!base || !token) { node.error("Set HA_URL and HA_TOKEN before reading a sensor."); return null; }
msg.questionOptions = msg.payload && typeof msg.payload === "object" ? {...msg.payload} : {};
msg.sensorRead = true; msg.method = "GET";
msg.url = base.replace(/\/+$/, "") + "/api/states/" + encodeURIComponent(sensor);
msg.headers = {Authorization: "Bearer " + token};
return [msg, null];
